exercises.solutionCode:
class NavStack {
  final List<String> _stack = [];

  void push(String route) {
    _stack.add(route);
  }

  String? pop() {
    if (_stack.isEmpty) return null;
    return _stack.removeLast();
  }

  String? current() {
    if (_stack.isEmpty) return null;
    return _stack.last;
  }

  int length() {
    return _stack.length;
  }

  List<String> history() {
    return List.from(_stack);
  }
}

void main() {
  final nav = NavStack();
  nav.push('/home');
  nav.push('/profile');
  nav.push('/settings');

  print('Current: ${nav.current()}');
  print('Length: ${nav.length()}');
  print('History: ${nav.history()}');

  final popped = nav.pop();
  print('Popped: $popped');
  print('Current: ${nav.current()}');
}

