class Router {
  final Map<String, Function> _routes = {};

  void register(String route, Function handler) {
    _routes[route] = handler;
  }

  dynamic navigate(String route) {
    final handler = _routes[route];
    if (handler == null) {
      return '404: $route';
    }
    return handler();
  }

  bool hasRoute(String route) {
    return _routes.containsKey(route);
  }

  List<String> routes() {
    return _routes.keys.toList();
  }
}

void main() {
  final router = Router();
  router.register('/home', () => 'Home Page');
  router.register('/about', () => 'About Page');
  router.register('/profile', () => 'Profile Page');

  print(router.navigate('/home'));
  print(router.navigate('/about'));
  print(router.navigate('/missing'));
  print('Routes: ${router.routes()}');
}

