class RouteParser {
  Map<String, dynamic> parse(String url) {
    final questionIndex = url.indexOf('?');
    if (questionIndex == -1) {
      return {'path': url, 'params': {}};
    }

    final path = url.substring(0, questionIndex);
    final queryString = url.substring(questionIndex + 1);
    final params = <String, String>{};

    for (final pair in queryString.split('&')) {
      final eqIndex = pair.indexOf('=');
      if (eqIndex != -1) {
        final key = pair.substring(0, eqIndex);
        final value = pair.substring(eqIndex + 1);
        params[key] = value;
      }
    }

    return {'path': path, 'params': params};
  }

  String build(String path, Map<String, String> params) {
    if (params.isEmpty) return path;
    final query = params.entries.map((e) => '${e.key}=${e.value}').join('&');
    return '$path?$query';
  }

  String? getParam(String url, String key) {
    final parsed = parse(url);
    final params = parsed['params'] as Map<String, String>?;
    return params?[key];
  }
}

void main() {
  final parser = RouteParser();

  final parsed = parser.parse('/users/123?page=2&sort=name');
  print('Parsed: $parsed');

  final built = parser.build('/search', {'q': 'dart', 'limit': '10'});
  print('Built: $built');

  final page = parser.getParam('/users?page=2&size=10', 'page');
  print('Page: $page');
}
